local results=pack(temp(unpackValues(values,1,count)))
if c==0 then
local value=results.n
for item=1,value do registers[a+item-1]=results[item] end
top=a+value
else
for item=1,c-1 do registers[a+item-1]=results[item] end
end
elseif opcode==37 then
registers[a]=registers[b]..registers[c]
elseif opcode==18 then
registers[a]=registers[b]
elseif opcode==42 then
registers[a]=(registers[b]<registers[c])
elseif opcode==15 then
